//
//  Cross-check of the Swift port against the reference JS engine.
//
//  golden.json is generated by make_golden.js from the pinned reference
//  adaptive_engine.js: a full snapshot of every session and of the state after
//  every feedback step, per scenario. Scenarios may start from a seeded state,
//  may apply a decay and a series of comebacks, and may pull handles before
//  the plan — all replayed here exactly as the app would.
//
//  A divergence in even one number = a port error. Do not edit the fixture by
//  hand.
//

import XCTest
@testable import DredfitCore

// Disambiguate from the Pattern type introduced in the macOS 26 SDK
private typealias Pattern = DredfitCore.Pattern

final class GoldenTests: XCTestCase {

    private func loadGolden() throws -> Golden {
        let url = try XCTUnwrap(
            Bundle.module.url(forResource: "golden", withExtension: "json"),
            "golden.json not found in test resources")
        return try JSONDecoder().decode(Golden.self, from: Data(contentsOf: url))
    }

    /// The fixture must come from the pinned reference version — a fixture
    /// regenerated from the wrong adaptive_engine.js would silently
    /// re-baseline every number instead of catching a port bug.
    func testGeneratorIsThePinnedReferenceVersion() throws {
        let g = try loadGolden()
        XCTAssertEqual(g.generator, "adaptive_engine.js v3.0.0",
                       "golden.json regenerated from an unexpected reference version")
    }

    /// TEN patterns now, in one order for everything: the reference's
    /// `ALL_PATTERNS`. Separate `bar*` fields are gone, and with them the
    /// defect class "nine patterns have the field, the tenth was forgotten".
    func testPatternOrderMatchesReference() throws {
        let g = try loadGolden()
        XCTAssertEqual(g.patternOrder, Pattern.allCases.map(\.rawValue),
                       "pattern order diverged from the reference")
    }

    /// The dose grids, compared with the fixture rather than retyped.
    func testDoseGridsMatchReference() throws {
        let g = try loadGolden()
        for (name, grid) in g.dose {
            let unit = try XCTUnwrap(LoadUnit(rawValue: name))
            XCTAssertEqual(Dose.grid(unit).min, grid.min, "\(name) floor")
            XCTAssertEqual(Dose.grid(unit).max, grid.max, "\(name) ceiling")
            XCTAssertEqual(Dose.grid(unit).step, grid.step, "\(name) step")
        }
        XCTAssertEqual(Set(g.dose.keys), ["reps", "hold"])
    }

    /// The ladders themselves: length, difficulty, unit, sides, and the one
    /// probe-only boundary. Names are NOT compared — they are localized, and
    /// the fixture carries the Russian reference text; LibraryPinTests pins
    /// the identities through the library's own bundle instead.
    func testLaddersMatchReference() throws {
        let g = try loadGolden()
        XCTAssertEqual(g.library.values.reduce(0) { $0 + $1.count }, 59,
                       "§40.1: 59 positions across ten ladders")
        for p in Pattern.allCases {
            let rungs = try XCTUnwrap(g.library[p.rawValue], "\(p.rawValue) missing from the fixture")
            let entry = ExerciseLibrary.entry(for: p)
            XCTAssertEqual(entry.count, rungs.count, "\(p.rawValue): ladder length")
            for (i, rung) in rungs.enumerated() {
                let v = i + 1
                let mine = entry.variation(v)
                XCTAssertEqual(mine.w, rung.w, accuracy: 1e-12, "\(p.rawValue) v\(v): w")
                XCTAssertEqual(mine.unit.rawValue, rung.unit, "\(p.rawValue) v\(v): unit")
                XCTAssertEqual(mine.unilateral, rung.perSide, "\(p.rawValue) v\(v): sides")
                XCTAssertEqual(entry.probeOnly(variation: v), rung.probeOnly ?? false,
                               "\(p.rawValue) v\(v): probe-only boundary")
            }
        }
    }

    func testAllScenariosMatchReferenceEngine() throws {
        let g = try loadGolden()
        let order = try g.patternOrder.map { try XCTUnwrap(Pattern(rawValue: $0)) }
        for scenario in g.scenarios {
            var state = try seedState(scenario.seed, order: order)
            for (i, step) in scenario.steps.enumerated() {
                let ctx = "\(scenario.name)/step \(i + 1)"
                // The one settings toggle a scenario may flip between sessions.
                state.hasBar = step.own.hasBar ?? state.hasBar
                try replayBreaks(step, into: &state, order: order, ctx: ctx)
                try replayHandles(step, into: &state, order: order, ctx: ctx)

                let session = Engine.generateSession(state)
                assertSession(session, step: step, ctx: ctx)

                state = try replayFeedback(step, from: state, session: session,
                                           order: order, ctx: ctx)
                assertState(state, step.snapshot, order: order, ctx: ctx)
                assertGlobals(state, step.own, ctx: ctx)
            }
        }
    }

    // MARK: - Replay

    private func seedState(_ seed: Golden.Seed?, order: [Pattern]) throws -> EngineState {
        var state = EngineState.initial
        guard let seed else { return state }
        state.counter = seed.counter
        state.hasBar = seed.hasBar
        for (idx, p) in order.enumerated() {
            state.vars[p] = seed.vars[idx]
            state.doses[p] = seed.doses[idx]
            state.failStreak[p] = seed.failStreak[idx]
            if seed.sets[idx] != EngineConfig.setsBase { state.sets[p] = seed.sets[idx] }
            if seed.sub[idx] > 0 { state.sub[p] = seed.sub[idx] }
            if seed.cut[idx] > 0 { state.cut[p] = seed.cut[idx] }
            if seed.lastHard[idx] == 1 { state.lastHard.insert(p) }
        }
        state.shown = try decodeShown(seed.shown)
        return state
    }

    /// The breaks a step may carry, replayed in the app's order: the silent
    /// decay first, then the comeback (possibly a series with no session
    /// between them).
    private func replayBreaks(_ step: Golden.Step, into state: inout EngineState,
                              order: [Pattern], ctx: String) throws {
        if let decay = step.own.silentDecay {
            state = Engine.applySilentDecay(state: state, gapDays: decay.gapDays)
            assertState(state, decay.snapshot, order: order, ctx: "\(ctx) silent decay")
            assertStreaks(state, decay.failStreakAfter, order: order, ctx: "\(ctx) silent decay")
        }
        for (n, comeback) in (step.own.comeback?.snaps ?? []).enumerated() {
            state = Engine.applyComeback(state: state, gapDays: comeback.gapDays,
                                         alreadyDecayed: comeback.alreadyDecayed ?? false)
            let cctx = "\(ctx) comeback[\(n)]"
            assertState(state, comeback.snapshot, order: order, ctx: cctx)
            assertStreaks(state, comeback.failStreakAfter, order: order, ctx: cctx)
            XCTAssertEqual(state.counter, comeback.counterAfter,
                           "\(cctx) must not move the counter")
            XCTAssertEqual(state.returnRun, comeback.returnRunAfter, "\(cctx) (return run)")
        }
    }

    /// Handles land where the app applies them — after any break, before the
    /// plan is generated.
    ///
    /// The ORDER inside a step is part of the contract and is fixed here to
    /// match the reference: the easier-variation handle first (it changes the
    /// variation and zeroes every other coordinate), then a per-movement cut.
    /// Running them the other way round would let the first erase the
    /// second's work. `setCut` is walked in sorted key order because a Swift
    /// Dictionary has none and the reference's object literal does — each cut
    /// touches only its own pattern, so the walk is deterministic either way.
    private func replayHandles(_ step: Golden.Step, into state: inout EngineState,
                               order: [Pattern], ctx: String) throws {
        guard let h = step.own.handles else { return }
        for raw in h.easierVariation ?? [] {
            state = Engine.easierVariation(state: state,
                                           pattern: try XCTUnwrap(Pattern(rawValue: raw)))
        }
        for (raw, value) in (h.setCut ?? [:]).sorted(by: { $0.key < $1.key }) {
            state = Engine.setCut(state: state,
                                  pattern: try XCTUnwrap(Pattern(rawValue: raw)), cut: value)
        }
        assertState(state, h.snapshot, order: order, ctx: "\(ctx) handles")
    }

    /// The feedback of one step, and the sets skipped while doing it.
    ///
    /// Rule 1 (§38.2): a skip lands through the entry point that owns the
    /// order, so this replay cannot get it wrong even by accident. A step
    /// without `skipSets` goes through the plain call.
    ///
    /// SEVEN arguments on that plain call, every optional passed explicitly —
    /// the rule of the wave, kept because a default silently shifting is
    /// exactly what an arity change does to a caller nobody updated.
    private func replayFeedback(_ step: Golden.Step, from state: EngineState,
                                session: Session, order: [Pattern],
                                ctx: String) throws -> EngineState {
        let result = try XCTUnwrap(FeedbackResult(rawValue: step.own.result))
        let overrides = try patternKeyed(step.own.overrides)
        let probes = try patternKeyed(step.own.probes ?? [:])
        let skipped = Set(try (step.own.skipped ?? []).map { try XCTUnwrap(Pattern(rawValue: $0)) })
        let setsSkipped = try patternKeyed(step.own.skipSets ?? [:])
        guard !setsSkipped.isEmpty else {
            return Engine.applyFeedback(state: state, session: session, result: result,
                                        overrides: overrides, skipped: skipped,
                                        gapDays: step.own.gapDays, probes: probes)
        }
        // The cut BEFORE the skip is asserted first: it is the one number that
        // separates "fed back, then skipped" from "skipped, then fed back",
        // and without it the fixture would pin the destination while leaving
        // the road open.
        if let before = step.own.cutBeforeSkip {
            let feedbackOnly = Engine.applyFeedback(
                state: state, session: session, result: result, overrides: overrides,
                skipped: skipped, gapDays: step.own.gapDays, probes: probes)
            XCTAssertEqual(order.map { feedbackOnly.cutOf($0) }, before,
                           ctx + " (cut before the skip)")
        }
        return Engine.applyFeedback(state: state, session: session, result: result,
                                    overrides: overrides, skipped: skipped,
                                    setsSkipped: setsSkipped, gapDays: step.own.gapDays,
                                    probes: probes)
    }

    // MARK: - Assertions

    private func assertSession(_ session: Session, step: Golden.Step, ctx: String) {
        XCTAssertEqual(session.sessionNumber, step.own.sessionNumber, ctx)
        XCTAssertEqual(session.warmupMin, step.own.warmupMin, ctx + " (warm-up)")
        XCTAssertEqual(session.cooldownMin, step.own.cooldownMin, ctx + " (cool-down)")
        XCTAssertEqual(session.estimatedTotalMin, step.own.estimatedTotalMin,
                       accuracy: 0.051, ctx + " (duration)")
        XCTAssertEqual(session.exercises.count, step.own.exercises.count, ctx)
        for (ex, ref) in zip(session.exercises, step.own.exercises) {
            XCTAssertEqual(ex.pattern.rawValue, ref.pattern, ctx)
            XCTAssertEqual(ex.variation, ref.variation, ctx + " \(ref.pattern) variation")
            XCTAssertEqual(ex.unit.rawValue, ref.unit, ctx + " \(ref.pattern) unit")
            XCTAssertEqual(ex.load, ref.load, ctx + " \(ref.pattern) load")
            XCTAssertEqual(ex.perSide, ref.perSide, ctx + " \(ref.pattern) sides")
            XCTAssertEqual(ex.sets, ref.sets, ctx + " \(ref.pattern) sets")
            XCTAssertEqual(ex.restSetSec, ref.restSetSec, ctx + " \(ref.pattern) rest")
            XCTAssertEqual(ex.restExerciseSec, ref.restExerciseSec, ctx)
            // The per-set doses, absence included — a uniform plan must stay
            // nil on both sides.
            XCTAssertEqual(ex.loads, ref.loads, ctx + " \(ref.pattern) loads")
            assertProbe(ex, ref, ctx: ctx)
        }
    }

    /// The probe, absence included: a plan that grew one where the reference
    /// has none is as much a port bug as a wrong number in it.
    private func assertProbe(_ ex: SessionExercise, _ ref: Golden.Ex, ctx: String) {
        guard let refProbe = ref.probe else {
            XCTAssertNil(ex.probe, ctx + " \(ref.pattern) must carry no probe")
            return
        }
        guard let probe = ex.probe else {
            XCTFail(ctx + " \(ref.pattern) must carry a probe")
            return
        }
        XCTAssertEqual(probe.variation, refProbe.variation, ctx + " \(ref.pattern) probe variation")
        XCTAssertEqual(probe.unit.rawValue, refProbe.unit, ctx + " \(ref.pattern) probe unit")
        XCTAssertEqual(probe.load, refProbe.load, ctx + " \(ref.pattern) probe load")
        XCTAssertEqual(probe.perSide, refProbe.perSide, ctx + " \(ref.pattern) probe sides")
    }

    /// Every coordinate of every position, plus the journal and the counters
    /// a snapshot carries. Written once and called from the step, the break
    /// and the handle pull alike — gating a field by the shape of the record
    /// is exactly the hole P0-5 of the 2026-08-20 audit came through.
    private func assertState(_ state: EngineState, _ snap: Golden.Snapshot,
                             order: [Pattern], ctx: String) {
        XCTAssertEqual(order.map { state.vars[$0] ?? -1 }, snap.varsAfter, ctx + " (vars)")
        XCTAssertEqual(order.map { state.sets[$0] ?? EngineConfig.setsBase }, snap.setsAfter,
                       ctx + " (sets)")
        XCTAssertEqual(order.map { state.doses[$0] ?? -1 }, snap.dosesAfter, ctx + " (doses)")
        XCTAssertEqual(order.map { state.sub[$0] ?? 0 }, snap.subAfter, ctx + " (sub)")
        XCTAssertEqual(order.map { state.cutOf($0) }, snap.cutAfter, ctx + " (cut)")
        XCTAssertEqual(order.map { state.lastHard.contains($0) ? 1 : 0 }, snap.lastHardAfter,
                       ctx + " (last hard)")
        XCTAssertEqual(order.map { state.setsHold[$0] ?? 0 }, snap.setsHoldAfter,
                       ctx + " (sets hold)")
        XCTAssertEqual(order.map { state.shownWork[$0] ?? 0 }, snap.shownWorkAfter,
                       ctx + " (shown work)")
        XCTAssertEqual(order.map { state.shownOrd[$0] ?? 0 }, snap.shownOrdAfter,
                       ctx + " (shown position)")
        XCTAssertEqual(state.rampWindow, snap.rampWindowAfter, ctx + " (ramp window)")
        XCTAssertEqual(order.map { state.weekGain[$0] ?? 0 }, snap.weekGainAfter,
                       ctx + " (weekly gain)")
        XCTAssertEqual(state.weekAgeDays, snap.weekAgeDaysAfter, accuracy: 1e-9,
                       ctx + " (window age)")
        assertJournal(state, snap.shownAfter, ctx: ctx)
    }

    /// The journal of what was shown — doubly sparse on both sides, so an
    /// entry the port invented fails as loudly as one it lost.
    private func assertJournal(_ state: EngineState, _ expected: [String: [String: Int]],
                               ctx: String) {
        var actual: [String: [String: Int]] = [:]
        for (p, row) in state.shown where !row.isEmpty {
            actual[p.rawValue] = Dictionary(uniqueKeysWithValues:
                row.map { (String($0.key), $0.value) })
        }
        XCTAssertEqual(actual, expected, ctx + " (journal of what was shown)")
    }

    private func assertStreaks(_ state: EngineState, _ expected: [Int],
                               order: [Pattern], ctx: String) {
        XCTAssertEqual(order.map { state.failStreak[$0] ?? -1 }, expected, ctx + " (failStreak)")
    }

    private func assertGlobals(_ state: EngineState, _ own: Golden.StepFields, ctx: String) {
        XCTAssertEqual(state.counter, own.counterAfter, ctx + " (counter)")
        XCTAssertEqual(Pattern.allCases.map { state.failStreak[$0] ?? -1 }, own.failStreakAfter,
                       ctx + " (failStreak)")
        XCTAssertEqual(state.lessRun, own.lessRunAfter, ctx + " (less run)")
        var hist: [String: Int] = [:]
        for (p, mask) in state.lessHist where mask > 0 { hist[p.rawValue] = mask }
        XCTAssertEqual(hist, own.lessHistAfter, ctx + " (appearance window)")
        XCTAssertEqual(state.returnRun, own.returnRunAfter, ctx + " (return run)")
        XCTAssertEqual([Pattern.pull, .pullBar].map { state.creditPaused.contains($0) ? 1 : 0 },
                       own.creditPausedAfter, ctx + " (credit paused)")
    }

    // MARK: - Small conversions

    private func patternKeyed(_ src: [String: Int]) throws -> [Pattern: Int] {
        var out: [Pattern: Int] = [:]
        for (raw, value) in src { out[try XCTUnwrap(Pattern(rawValue: raw))] = value }
        return out
    }

    private func decodeShown(_ src: [String: [String: Int]]) throws -> [Pattern: [Int: Int]] {
        var out: [Pattern: [Int: Int]] = [:]
        for (raw, row) in src {
            let p = try XCTUnwrap(Pattern(rawValue: raw))
            var dst: [Int: Int] = [:]
            for (v, dose) in row { dst[try XCTUnwrap(Int(v))] = dose }
            out[p] = dst
        }
        return out
    }
}
